import json,pathlib
P=pathlib.Path(__file__).parent
load=lambda n:json.loads((P/n).read_text())
def save(n,d):(P/n).write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
r=load('events.json')
for x in r:
 x['dateBasis']='Explicit dated event in opened reporting; date is observation, not onset or end.'
 if x['id']=='pr-fr-education-oct2026':x['dateBasis']='Le Monde explicitly describes October 13 activity; article URL dates October 14 but relative timestamp is inconsistent.'
 if x['id']=='pr-in-hostels-2026':x['dateBasis']='Unknown event date; October 5 is source publication only.'
 if x['id']=='pr-bd-accountability-2024':x['date']=None;x['last_observed_at']=None;x['dateBasis']='Historical episode July–August 2024. Opened summary does not date the named killing precisely.';x['event_date_interval']={'start':'2024-07-01','end':'2024-08-15'}
 if x['id']=='pr-np-allegations-2025':x['dateBasis']='Letter dated January 8, 2026 explicitly refers to September 8–9, 2025 protests; not current activity.'
 if x['id']=='pr-nz-firefighters-20261007':x['dateBasis']='Employer dated statement explicitly confirms October 7 strike; no city inferred.'
 x['claim_type']='attributed allegation' if x['id']=='pr-np-allegations-2025' else ('official fact-finding assessment' if x['id']=='pr-bd-accountability-2024' else 'attributed report')
 x['date_precision']='unknown' if x['date'] is None else 'day'
save('events.json',r)
relations=[{'id':'pr-link-greenpeace-kenya-za','from':'pr-ke-forests-20261006','to':'pr-za-energy-20261013','type':'shared publicly named participant organization','organization':'Greenpeace Africa','sourceIds':['pr-ke-k24-1006','pr-za-ap-1013'],'evidence_status':'supported limited association','interpretation':'Reports name Greenpeace Africa in both episodes.','does_not_establish':['shared funding','central direction','same individual participants','covert coordination','illegality']}, {'id':'pr-link-fr-ie-education','from':'pr-fr-education-oct2026','to':'pr-ie-public-pay-20261014','type':'analytical comparison only','sourceIds':['pr-fr-lm-1014','pr-ie-sin-1014'],'evidence_status':'theme similarity, no organizational edge','interpretation':'Both include public-service resource grievances; national institutions and constituencies differ.','does_not_establish':['shared organizer','funding transfer','causal influence']},{'id':'pr-link-india-comparison','from':'pr-in-electoral-oct2026','to':'pr-in-hostels-2026','type':'within-country comparison only','sourceIds':['pr-in-toi-1007','pr-in-ie-1005'],'evidence_status':'distinct grievances, no organizational edge','interpretation':'Electoral accountability and hostel conditions are separately reported claims.','does_not_establish':['one movement','same organization','same funding','common conspiracy']}]
save('relations.json',relations)
rejected=[{'id':'pr-reject-coordination','proposed_join':'Similar youth, education or cost-of-living protests -> common hidden funder','decision':'rejected','reason':'No payment, grant, ownership or direction record. Shared grievances are expected under independent local pressures.','needed_record':'Specific grant/transaction disclosure, recipient identity and purpose plus independent corroboration.'},{'id':'pr-reject-albania','proposed_join':'Tirana October 14 student rally -> earlier coastal-development rallies','decision':'unresolved; do not merge','reason':'Caption supplies no organizer or movement continuity evidence.','needed_record':'Contemporaneous local reporting of demands and named public organizers.'},{'id':'pr-reject-kenya-date','proposed_join':'K24 October 6 forest petition -> Standard October 10 photo caption','decision':'not merged','reason':'Later search hit has differing date and original failed to open. Cannot treat as independent corroboration or second event.','needed_record':'Original article body and dated organizer statement.'},{'id':'pr-reject-nz-dateline','proposed_join':'Union media index October 14 page metadata -> October 17 strike observation','decision':'rejected','reason':'Opened page dates that particular item October 17, 2025. Index metadata is not item/event date.','needed_record':'Dated individual release and occurrence report.'},{'id':'pr-reject-violence','proposed_join':'Clashes near Brussels union march -> all unions violent','decision':'rejected','reason':'Union denial and report of peaceful union march contradict conflation.','sourceIds':['pr-be-eur-1009']},{'id':'pr-reject-bd-np-procedure','proposed_join':'UN allegations letters and fact-finding findings -> criminal convictions','decision':'rejected','reason':'Different evidentiary/procedural standards. Neither opened source establishes conviction.','needed_record':'Signed judgment, defendant identity, disposition and appeal status.'},{'id':'pr-reject-absence','proposed_join':'No event record -> no protest in city/country','decision':'rejected','reason':'Convenience sample, incomplete language and indexing coverage, no global city denominator.'}]
save('rejected-joins.json',rejected)
rounds=[{'round':1,'name':'Source collection and denominator audit','decision':'Preserve 84 inherited episodes separately. Add 18 opened sources and 13 supplementary records without claiming all baseline sources rechecked.','source_window':'2025-02-12 through 2026-10-14 publications, plus undated union context; historical protest context back to July 2024','coverage':'249 country/territory roster; 123 city rows; 12 countries with selected supplemental checks, three previously missing countries represented.','limits':'No exhaustive global city roster, population denominator, or ongoing-activity guarantee.'},{'round':2,'name':'Candidate connections and alternative explanations','decision':'Keep one narrow shared-organization association and two clearly non-causal comparison relationships. No finance or hidden-direction edge supported.','competing_explanations':[{'hypothesis':'Independent local grievances','expected':'Distinct demands, national negotiations and different responses','observed':'Education funding, election administration, forest policy, pay bargaining and international solidarity differ.'},{'hypothesis':'Cross-event public organizational participation','expected':'Same named public organization in independent event reporting','observed':'Greenpeace Africa named in Nairobi and Cape Town reporting; financial coordination not established.'},{'hypothesis':'Apparent cross-border wave partly due to source selection','expected':'English-language and highly visible city overrepresentation','observed':'Supplement predominantly English; two Spanish sources, limited local-language coverage.'}]},{'round':3,'name':'Falsification and provenance review','decision':'Retain EC response, union disavowal of rioters, employer/union dispute perspectives, government energy rationale and UN procedural caveats adjacent to claims.','corrections':['Pune overview publication date removed as event date.','Bangladesh named killing precise date removed; period retained.','Nepal letter classified as allegations, not finding.','National New Zealand strike not assigned automatically to capital.','Unopened Kenya alternative not counted as corroboration.','City reference points not treated as event locations.'],'rejected_join_ids':[x['id'] for x in rejected],'review_status':'Self-check completed; independent peer review requested and timing correction confirmed.'}]
save('research-rounds.json',rounds)
queue=[{'id':'pr-next-india-orders','priority':'high','country':'IN','custodian':'Supreme Court of India official judgments/orders portal','record':'Signed October 9 and 11, 2026 orders concerning Delhi protest restrictions; docket identity and October 13 listing','success':'Match case identifiers and operative directions; do not infer October 15 disposition before it occurs.','authorization':'read-only public records'},{'id':'pr-next-country-gaps','priority':'high','country':None,'custodian':'National statistical gazetteers, municipal portals, national human rights institutions, reliable local-language outlets','record':'Country batches drawn from not-reviewed coverage rows, with city gazetteer and explicit query/source list','success':'Each selected country has dated acquisition log, positive or unresolved findings, and sources actually opened; no negative no-protest coding.','authorization':'read-only public records'},{'id':'pr-next-np-response','priority':'high','country':'NP','custodian':'UN Special Procedures communications database and Nepal judicial commission','record':'Government response to AL NPL 1/2025 and publicly released commission report','success':'Match communication identity; report allegations, response and findings separately.','authorization':'read-only public records'},{'id':'pr-next-bd-report','priority':'high','country':'BD','custodian':'OHCHR','record':'Full February 2025 fact-finding report and later public court judgments','success':'Page-level verification of named case and legal disposition without extending attribution beyond findings.','authorization':'read-only public records'},{'id':'pr-next-albania-demands','priority':'medium','country':'AL','custodian':'Reliable Albanian reporting and public institutional releases','record':'October 14 student demands and official response','success':'Upgrade caption-only occurrence to source-grounded episode narrative; assess continuity without assuming it.','authorization':'read-only public records'},{'id':'pr-next-finance','priority':'medium','country':None,'custodian':'Relevant public grant registers and organizational annual reports','record':'Only named and falsifiable proposed financing paths','success':'Require legal entity match, disclosed amount/date/purpose and relation to the specific activity; no blanket network accusations.','authorization':'read-only public records'}]
save('research-queue.json',queue)
# Supplemental claims are literal proposition records, not hidden-network conclusions.
claims=[]
for x in r:
 claims.append(dict(id=x['id']+'-claim',record_id=x['id'],statement=x['summary'],claim_type=x['claim_type'],sourceIds=x['sourceIds'],date=x['date'],date_basis=x['dateBasis'],contrary_evidence=x['contrary_evidence'],cannot_establish=['undisclosed financing','criminal guilt','current uninterrupted activity','exhaustive participants'],review_status='source-checked; independent peer review pending'))
save('claims.json',claims)
# Hashes are local dataset identity, not source authenticity certification.
save('packet-manifest.json',[dict(file=p.name,sha256=__import__('hashlib').sha256(p.read_bytes()).hexdigest()) for p in sorted(P.glob('*.json')) if p.name!='packet-manifest.json'])
print('Finalized',len(r),'records',len(relations),'relationships',len(rejected),'rejected/unresolved joins')
